W += [
E('alkaloid','/ˈælkəlɔɪd/','生物碱','一类常见于植物等生物体、通常含氮并有生理活性的有机物。','alkali 碱 + -oid 类似的；命名抓住许多成员表现出的碱性，不是说它们就是普通无机碱。',OID+[['近代 alkali + -oid → alkaloid','像碱的 → 生物碱这一类有机物']],'caffeine is an alkaloid 说咖啡因属于生物碱。这个类别内部作用差别很大；天然来源并不等于没有毒性，也不是每种都呈强碱性。','plant alkaloids；an alkaloid compound；isolate an alkaloid。','alkali 是碱；alkaloid 是特定有机物类别。两者名称相关，但不能互相替换。',('Caffeine is an alkaloid found in coffee and tea.','咖啡因是一种存在于咖啡和茶中的生物碱。'),('The researchers isolated an alkaloid from the plant sample.','研究人员从植物样品中分离出一种生物碱。'),sources=['https://www.etymonline.com/word/alkaloid','https://www.merriam-webster.com/dictionary/alkaloid']),
E('ovoid','英 /ˈəʊvɔɪd/；美 /ˈoʊvɔɪd/','卵形的；卵状体','像一只鸡蛋那样圆润、略长，一端常比另一端窄。','拉丁 ovum 蛋 + 希腊来源 -oid；混合不同语言来源成分的学术造词。',OID+[['拉丁 ovum + -oid → 英语 ovoid','蛋 + 像……的 → 卵形的、卵状物']],'an ovoid stone 是卵形石头；ovoid seeds 是卵形种子。多用于外形描述，不说明物体真的是卵。','an ovoid shape；an ovoid stone；ovoid seeds。','oval 常说椭圆或卵形轮廓；ovoid 尤其容易让人想到立体的蛋状形体，不一定是严格数学椭球。',('The vase has a smooth ovoid body.','花瓶的主体呈圆润的卵形。'),('Several small ovoid stones lay beside the stream.','溪边有几块卵形小石头。'),sources=['https://en.wiktionary.org/wiki/ovoid#English','https://www.merriam-webster.com/dictionary/ovoid']),
E('cannabinoid','美 /kəˈnæbəˌnɔɪd/','大麻素；大麻素类物质','一类最初与大麻成分联系起来的物质名称，也用于相关的体内自产或合成物质。','cannab- 来自 cannabis，接 -in 与 -oid 构成；现代名称范围扩展到结构或作用相关的物质。',OID+[['cannabis 相关词干 cannab- + -in + -oid → cannabinoid','大麻相关成分 → 大麻素及相关物质类别']],'plant cannabinoids 是植物来源的大麻素；endogenous cannabinoids 是体内自身产生的内源性大麻素。不同成员作用不同，不能把全部成员直接等同会产生醉感的 THC。','a cannabinoid compound；cannabinoid receptors；synthetic cannabinoids。','cannabis 是植物及相关制品名称；cannabinoid 是化学物质类别，不等于植物本身。',('The paper distinguishes plant cannabinoids from compounds produced within the body.','论文区分了植物大麻素与人体自身产生的相关化合物。'),('The researchers studied how the compound interacts with cannabinoid receptors.','研究人员研究了这种化合物如何与大麻素受体相互作用。'),sources=['https://en.wiktionary.org/wiki/cannabinoid#English','https://www.merriam-webster.com/dictionary/cannabinoid']),
E('ellipsoid','/ɪˈlɪpsɔɪd/','椭球；椭球体','把一个球沿不同方向拉伸或压缩，得到仍然光滑、对称的立体形状。','ellips- 椭圆相关词干 + -oid；词干接希腊 elleipsis，经拉丁数学用语传承。现代可联系 ellipse 理解，不把现代英语名词的记录先后当作唯一造词路线。',[['希腊 elleipsis → 拉丁数学用语 ellipsis','椭圆的历史名称'],['学术构词 ellips- + -oid → 英语 ellipsoid','椭圆相关形体 → 椭球']],'model the Earth as an ellipsoid 是把地球近似建模为椭球。它不是随便一个看着圆的石头，而是有明确几何性质的形体。','an ellipsoid model；the surface of an ellipsoid；a reference ellipsoid。','ellipse 是二维椭圆；ellipsoid 是三维椭球。鸡蛋一端尖、一端宽，通常不是严格的椭球。',('The software represents the planet as an ellipsoid.','软件把这颗行星表示为一个椭球。'),('Stretching a sphere along one axis produces an ellipsoid.','把球沿一个轴拉伸，可以得到椭球。'),sources=['https://www.etymonline.com/word/ellipsoid','https://www.merriam-webster.com/dictionary/ellipsoid','https://en.wiktionary.org/wiki/ellipsoid#English']),
E('haploid','/ˈhæplɔɪd/','单倍体的；单倍体','细胞里只有一套染色体，重点是一套，不是一条。','haplo- 单一，接希腊 haploos 单的 + -oid；现代遗传学用来标明染色体组数。',OID+[['希腊 haploos 单的 → haplo- + -oid → 英语 haploid','单一的一套 → 单倍体的']],'a haploid cell 是单倍体细胞；人类正常精子、卵细胞各有一套染色体。套里可以有许多条，所以不能把单倍理解成单根染色体。','a haploid cell；a haploid organism；a haploid set。','diploid 是有两套染色体；haploid 是一套。倍性说的是套数，不是细胞体积大小。',('A human sperm cell normally contains a haploid set of chromosomes.','人类精子通常含有一套染色体。'),('The diagram compares haploid and diploid cells.','图中比较了单倍体细胞与二倍体细胞。'),sources=['https://en.wiktionary.org/wiki/haploid#English','https://www.genome.gov/genetics-glossary/haploid']),
E('colloid','英 /ˈkɒlɔɪd/；美 /ˈkɑːlɔɪd/','胶体','细小颗粒或微小区域分散在另一种介质里，形成介于分子尺度与肉眼大块之间的体系。','借法语 colloïde，取希腊 kolla 胶 + -oeidēs；早期由胶样性质命名，现代胶体不要求看起来黏糊糊。',COLLOID,'milk as a colloid 是用牛奶说明胶体体系；胶体可以涉及液体、固体或气体，重点是分散结构的尺度。不能把凡是透明的都当真溶液，也不能把胶体只等同胶水。','a colloid system；form a colloid；particles in a colloid。','solution 在狭义化学语境常指分子、离子尺度均匀分散的真溶液；colloid 的分散结构尺度通常更大。',('The class used milk as an example of a colloid.','课堂上用牛奶作为胶体的例子。'),('The researchers measured the particle size in the colloid.','研究人员测量了胶体中的颗粒大小。'),sources=['https://www.etymonline.com/word/colloid','https://en.wiktionary.org/wiki/colloid#English','https://goldbook.iupac.org/terms/view/C01172']),
E('colloidal','英 /ˌkɒˈlɔɪdəl/；美 /kəˈlɔɪdəl/','胶体的；胶态的','说明物质以细微分散结构存在，而不是已经变成一大块或完全按单个小分子分散。','colloid + -al；形容词重音在 /lɔɪ/ 音节，与名词常用重音不同。',COLLOID+[['英语 colloid + -al → colloidal','胶体 → 处于胶体分散状态的']],'colloidal particles 是胶体颗粒；colloidal silica 是胶体二氧化硅。典型尺度大致在纳米至微米范围，但界限与所考察的性质有关，不必把它背成毫无例外的硬线。','colloidal particles；colloidal silica；a colloidal dispersion。','colloidal 描写分散状态，不是产品功效保证；加上这个词不自动代表更安全或更有效。',('The coating contains a colloidal dispersion of silica.','这种涂层含有二氧化硅胶体分散液。'),('The experiment examines how colloidal particles aggregate.','实验研究胶体颗粒如何聚集。'),sources=['https://www.collinsdictionary.com/dictionary/english/colloidal','https://en.wiktionary.org/wiki/colloidal#English','https://goldbook.iupac.org/terms/view/C01172']),
E('fibroid','/ˈfaɪbrɔɪd/','肌瘤，尤指子宫肌瘤；纤维状的','日常健康资料里通常指子宫内或周围的一种良性增生。','fibro- 纤维，接拉丁 fibra + -oid 像……的；早期形容纤维样组织，名词从 fibroid tumour 等表达发展。',OID+[['拉丁 fibra → fibro- + -oid → 英语 fibroid〔形容词〕','纤维样的'],['fibroid tumour → fibroid〔名词〕','常指含肌肉与纤维组织的良性肌瘤，尤见于子宫']],'uterine fibroids 是子宫肌瘤，属于非癌性生长。这个名称不意味着所有纤维组织都长成瘤，也不能仅凭词义判断个人症状。','uterine fibroids；a fibroid was found；the size of a fibroid。','fibrosis 是纤维化这一组织变化，fibroid 常是一个具体的良性肌瘤，两者不是同义词。',('The scan showed a small uterine fibroid.','扫描显示有一个小的子宫肌瘤。'),('The leaflet explains that fibroids are non-cancerous growths.','手册解释说，肌瘤是非癌性的增生。'),sources=['https://www.merriam-webster.com/dictionary/fibroid','https://en.wiktionary.org/wiki/fibroid#English','https://www.nhs.uk/conditions/fibroids/']),
E('spheroid','英 /ˈsfɪərɔɪd/；美 /ˈsfɪrɔɪd/','近球体；旋转椭球体','像球，但可能沿一个方向被压扁或拉长。','经拉丁 sphaeroides 接希腊 sphairoeidēs 球状的；sphaira 球 + -oeidēs，不是所有历史都从现代英语 sphere 新加后缀开始。',OID+[['希腊 sphaira + -oeidēs → sphairoeidēs → 拉丁 sphaeroides → 英语 spheroid','像球的 → 近球体、旋转椭球体']],'an oblate spheroid 是扁球体；a prolate spheroid 是长球体。几何里通常指椭圆绕一条主轴旋转所得的椭球，日常科学描述也可较宽泛说近球形体。','an oblate spheroid；a prolate spheroid；a spheroid model。','sphere 是球；ellipsoid 范围更广。常用几何意义的 spheroid 有两个相等的半轴。',('The Earth is often approximated as an oblate spheroid.','地球常被近似为扁球体。'),('The model stretched the sphere into a prolate spheroid.','模型把球拉长成了长球体。'),sources=['https://www.etymonline.com/word/spheroid','https://www.oxfordlearnersdictionaries.com/definition/english/spheroid','https://www.merriam-webster.com/dictionary/spheroid']),
E('sigmoid','/ˈsɪɡmɔɪd/','S 形的；乙状结肠；S 形函数','形状先弯向一边，再弯回来，像拉长的 S。','借希腊 sigmoeidēs，来自 sigma 字母名与表示形状的 -oeidēs；现代可辨 sigma 与 -oid。早期联系 sigma 的 C 状写法，后来常指 S 形，不能只拿大写 Σ 的现代印刷外形硬比。',OID+[['希腊 sigma + -oeidēs → sigmoeidēs → 英语 sigmoid','借入像 sigma 字形的古典形容词；现代可辨 -oid 后缀'],['常见现代专门用法','乙状结肠；数学与计算中的 S 形曲线或函数']],'sigmoid colon 是乙状结肠；sigmoid curve 是 S 形曲线。在机器学习里 the sigmoid 常特指 logistic sigmoid，但更一般的 sigmoid 可指一类 S 形函数。','a sigmoid curve；the sigmoid colon；a sigmoid function。','logistic function 是常见的 sigmoid 函数；不能倒过来说每条 S 形曲线都只有这一个公式。',('The graph follows a sigmoid curve, rising slowly and then more quickly before levelling off.','图线呈 S 形，先缓慢上升，再加快，最后趋于平缓。'),('The diagram labels the sigmoid colon.','图中标出了乙状结肠。'),sources=['https://www.etymonline.com/word/sigmoid','https://en.wiktionary.org/wiki/sigmoid#English','https://www.merriam-webster.com/dictionary/sigmoid']),
E('cuboid','/ˈkjuːbɔɪd/','长方体；近立方体的；骰骨','像一个盒子，长、宽、高可以不一样。','cube 立方体 + -oid 类似的；近代英语构词。另在解剖学中，cuboid bone 是脚部一块近立方形的骨。',OID+[['英语 cube + -oid → cuboid','像立方体的 → 长方体或近立方形物体'],['解剖名词 cuboid bone → cuboid','足部的骰骨']],'a rectangular cuboid 是长方体；在常见学校数学里 cuboid 本身通常就指长方体。它有六个矩形面，不必六个面都是正方形。','a cuboid box；a rectangular cuboid；the volume of a cuboid。','cube 的棱长都相等；cuboid 的长宽高可不同。骰骨是专门骨名，不是把脚说成一个盒子。',('The storage box is shaped like a cuboid.','收纳盒呈长方体形状。'),('To find the cuboid’s volume, multiply its length, width, and height.','求长方体体积时，把长、宽、高相乘。'),sources=['https://www.etymonline.com/word/cuboid','https://en.wiktionary.org/wiki/cuboid#English','https://www.merriam-webster.com/dictionary/cuboid']),
E('retinoid','美 /ˈretəˌnɔɪd/','维 A 类物质；类视黄醇','与维生素 A 在结构或作用上相关的一类天然或合成物质。','retin- 取自 retinol 视黄醇，再接 -oid；retinol 的名称又与 retina 视网膜及视觉相关背景相连，不是泛指像视网膜的东西。',OID+[['英语 retinol → retin- + -oid → retinoid','视黄醇相关 → 维 A 类物质']],'a topical retinoid 是外用维 A 类制剂；retinoid research 研究这类物质的作用。护肤品和药物里的成员不同，不宜把类别名当成某一个成分名。','a topical retinoid；retinoid compounds；retinoid treatment。','retinol 是其中一个具体成员；retinoid 是更广的类别，不能只凭名字断定产品强度相同。',('The article distinguishes retinol from the broader category of retinoids.','文章区分了视黄醇与更广泛的维 A 类物质。'),('The label lists a retinoid among the active ingredients.','标签在活性成分中列出了一种维 A 类物质。'),sources=['https://www.merriam-webster.com/dictionary/retinoid','https://en.wiktionary.org/wiki/retinoid#English']),
]
