DEFERRED={'amyloid':'较专门蛋白沉积相关术语，通用词族暂略。','carotenoid':'较专门天然色素类别，本轮暂略。','flavonoid':'较专门植物化学类别，本轮暂略。','lymphoid':'专门免疫组织形容词，暂略。','myeloid':'专门造血、骨髓相关形容词，暂略。','mucoid':'较专门黏液样形容词，暂略。','mongoloid':'带有歧视性的过时人种与医学用词，不列通用主动学习词。','decollate':'罕用砍头或印刷用语，暂略。','decollation':'较冷门砍头、印刷名词，暂略。','encollar':'罕用加项圈动词，优先 collar。','décolletage':'较专门服装与裸露颈胸部名词，暂略。','immiserate':'较专门政治经济动词，优先 impoverish，暂略。','immiseration':'较专门政治经济名词，暂略。','rudimental':'较少用基础形容词，优先 rudimentary。','rudity':'罕用粗陋、无知名词，优先 rudeness。','bucinator muscle':'多词解剖术语且原表拼写异常，暂不列入通用词族。'}
OID_ROOT=dict(id='C0870',meaning='像……的；具有相应形态、性质的一类',core='先找一个熟悉的样子，再说某物与它相像。但相像可以是外形，也可以是结构或作用，不能一律译成假的。',image='希腊 eidos 形状 → -eidēs / -oeidēs → 拉丁化 -oides → 英语 -oid；星状、球状、人形，再扩展到化学和医学的分类名称。',intro='asteroid 像星点，却不是恒星；humanoid 像人；spheroid 像球。近代科学里的 opioid、steroid 等已经有固定类别含义，知道后缀只能帮助记忆，不能代替定义。tabloid 从药片商标转向浓缩新闻，是另一个有意思的变化。',forms='-oid 通常读 /ɔɪd/。不是所有词都是在英语里现拼：spheroid 经希腊、拉丁传来，solenoid 和 colloid 有法语借入路线。colloidal 与 steroidal 的重音可能从基本词移到后面。',branches=[['外形与几何','humanoid, android, ovoid, ellipsoid, spheroid, cuboid, centroid'],['天文与媒体','asteroid, tabloid, celluloid, factoid'],['疑虑与心理表现','paranoia, paranoid'],['材料、电磁与化学','solenoid, colloid, colloidal, alkaloid, steroid, steroidal, cannabinoid, retinoid'],['健康阅读词','opioid, rheumatoid, typhoid, fibroid'],['细胞与形态','haploid, diploid, organoid, sigmoid']],contrasts='paranoia 是名词，paranoid 是形容词。ellipse 是二维，ellipsoid 是三维。typhoid 与 typhus 不是同一种疾病。retinoid 是类别，retinol 是其中一种具体物质。',practice='解释 asteroid 为什么不是小恒星；比较 cube 与 cuboid；用 tabloid 的历史说明后缀联想为什么不能替代完整词义。',words=list(dict.fromkeys([w for w in ASSIGN['roots'][110]['family'] if w not in DEFERRED]+['android'])),exclude={w:DEFERRED[w] for w in ASSIGN['roots'][110]['family'] if w in DEFERRED})
COL_ROOT=dict(id='C0244',meaning='脖子；围在颈部的东西',core='从脖子这一圈出发：衣领围住它，项圈套住它，锁骨在它下方；抱颈授礼又延伸为荣誉。',image='拉丁 collum 脖子 → collare → collar；法语 col 把山口比作脖子；围颈拥抱的礼仪一线 → accolade 赞誉。',intro='同一幅颈部画面，进入了衣着、宠物、登山与荣誉语言。collar 作动词还可以抓住、拦住别人。不是所有 coll- 开头的词都来自脖子，collision、college 不能仅按字母放进这一支。',forms='collar 的英式常读 /ˈkɒlə/，美式常读 /ˈkɑːlər/；accolade 的历史中 ad- 与 collum 相接，形成 acc-。collarbone 是英语复合词，不是拉丁整词借入。',branches=[['围着脖子与颈部附近','collar, collared, collarbone'],['授礼、赞誉','accolade'],['地形中的脖子','col']],contrasts='collar 是衣领或项圈，color 是颜色。col 是峰间低处，summit 是山顶。accolade 常比一句普通 compliment 更正式。',practice='用 collar 分别说衬衫和宠物，再用动词说拦住人；比较 col 与 summit；解释 accolade 为什么会与脖子有关。',words=[w for w in ASSIGN['roots'][111]['family'] if w not in DEFERRED],exclude={w:DEFERRED[w] for w in list(ASSIGN['roots'][111]['family'])+ASSIGN['roots'][111]['unmatched'] if w in DEFERRED})
MISER_ROOT=dict(id='C0750',meaning='痛苦、不幸、可怜',core='原本是一个人过得难受、处境可怜。有人陪他感叹，就有同情；守财奴则是后来形成的特别一支。',image='拉丁 miser 不幸的 → miseria → misery；miserabilis → miserable；miserari 怜悯 → commiserari → commiserate。英语 miser 再发展成守财奴。',intro='别用现代 miser 守财奴倒推所有词。miserable 不是能够当守财奴，而是痛苦、糟糕。commiserate 常用于朋友失利后表示同情；commiseration 有较早的法语、拉丁名词借入路线。',forms='miser、miserly 的首元音通常是 /aɪ/；misery、miserable、commiserate 相关音节通常是 /ɪ/。miserly 中 -ly 主要形成形容词，miserably 才是 miserable 的副词。',branches=[['难受与糟糕','miserable, misery, miserably'],['囤钱不舍得花','miser, miserly'],['一起感叹不顺','commiserate, commiseration'],['已有历史用词','misericord']],contrasts='frugal 可称赞节俭，miserly 常批评吝啬。commiserations 可为比赛失利表示安慰，condolences 多为丧亲慰问。com- 在 commiserari 中也可能有加强作用，不必硬画成大家一起悲惨。',practice='比较 miserly 与 miserably；为朋友比赛失利写一句带 commiserate 的安慰；说明存钱的人为什么不一定是 miser。',words=[w for w in ASSIGN['roots'][112]['family'] if w not in DEFERRED],exclude={w:DEFERRED[w] for w in ASSIGN['roots'][112]['family'] if w in DEFERRED})
RUD_ROOT=dict(id='C1237',meaning='粗糙、未经加工或训练；初步与受教',core='原材料还没打磨，技能还没训练；经过学习，才从起步阶段走向有学识。礼貌义也是从没有教养的旧联想发展来的。',image='拉丁 rudis 粗糙、未训练 → rude；rudimentum 初次尝试 → rudiment、rudimentary；e- 向外 + rudis → erudire 教育 → erudite、erudition。',intro='rude 最常说无礼，但 a rude awakening 不是礼貌问题，而是突然被现实惊醒。rudimentary 描写初步水平；erudite 则在另一端，强调学问丰富。不要把所有词都局限在骂人粗鲁上。',forms='rudiment 常用复数 rudiments 表示入门知识；rudimentary 的重音在 ment。erudite 与 erudition 分别接拉丁分词和名词，是并列的历史借入支线。',branches=[['礼貌与表现方式','rude, rudely, rudeness'],['起步的基本部分','rudiment, rudiments, rudimentary'],['受教后的广博知识','erudite, erudition']],contrasts='basic 可以是完备的基础，rudimentary 常暗示尚粗浅。intelligent 说理解能力，erudite 说积累的学识。直率 blunt 不一定等于 rude。',practice='用 rude awakening 描写一次现实冲击；比较 rudimentary knowledge 与 erudition；用 rudiments 说明初学者先学什么。',words=[w for w in ASSIGN['roots'][113]['family'] if w not in DEFERRED],exclude={w:DEFERRED[w] for w in ASSIGN['roots'][113]['family'] if w in DEFERRED})
BOV_ROOT=dict(id='C0131',meaning='牛；牛肉与强壮；boor 的来源分歧',core='牛变成餐桌上的肉，再借来形容块头和力量。另一组 boor、boorish 则主要来自农民的日耳曼词，不能直接用牛解释粗鲁。',image='拉丁 bos / bovis / bovem 牛 → 法语 boef → beef；拉丁 bovinus → bovine。另列 boor 的日耳曼主线与早期法语牧牛人合流说。',intro='beef 最常说牛肉，也能说不满、争执，beef up 则是加强；抱怨义的具体形成路线仍有争议。boor 的主要来源在 Oxford、MW 中是荷兰语或低地德语农民词，Etyonline 另提出古法语 bovier 与日耳曼词合流。保留分歧，比硬凑成一条直系更准确。',forms='bov- 是拉丁 bos 的屈折词干，英语 beef 经法语发生了形态变化。bovine 是学术借词，常读 /ˈbəʊvaɪn/ 或 /ˈboʊvaɪn/。boor 与 bore、boar 含义不同。',branches=[['牛与牛肉','beef, bovine, beefsteak'],['肌肉与力量的比喻','beefy, beefcake'],['来源分歧的传统关联','boor, boorish']],contrasts='cow 是动物常用名，beef 多指肉，bovine 是牛类相关形容词。beefy 不等于只是肥胖。boor 的旧乡村身份向无礼转义反映历史偏见，不是对农民的事实判断。',practice='用 beef 分别说食物和不满；用 beef up 说加强一项工作；区分 boor、bore、boar，说明为何不能都接 bov。',words=list(ASSIGN['roots'][114]['family']),exclude={w:DEFERRED[w] for w in ASSIGN['roots'][114]['unmatched'] if w in DEFERRED})
